new_invite='''export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  return issueInvitations(actor, input, null);
}

/**
 * Shared by bulk invite and resend. `replacing` names a pending invitation
 * that is being superseded: it neither blocks its own address nor holds a
 * seat against the replacement, and it is revoked once the new one exists.
 */
async function issueInvitations(
  actor: Actor,
  input: InviteMembersInput,
  replacing: InvitationId | null,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:invite", orgResource(input.orgId));

  const verdict = await consumeRateLimit(
    input.orgId,
    INVITE_BUCKET,
    input.invites.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const pending = (await invitationRepo.listPendingInvitations(input.orgId))
    .filter((row) => row.id !== replacing);
  const takenEmails = new Set<string>([
    ...(await memberRepo.listLiveMemberEmails(input.orgId)),
    ...pending.map((row) => row.email.toLowerCase()),
  ]);
  const batchEmails = new Set<string>();

  for (const invite of input.invites) {
    const email = invite.email.trim().toLowerCase();
    if (batchEmails.has(email)) {
      throw new Error(`${invite.email} is named more than once`);
    }
    batchEmails.add(email);
    if (takenEmails.has(email)) {
      throw new Error(
        `${invite.email} is already a member or has a pending invitation`,
      );
    }
  }

  const seatsUsed =
    (await memberRepo.countActiveMembers(input.orgId)) + pending.length;

  if (
    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
  ) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const invitations: Invitation[] = [];

  for (const invite of input.invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      input.orgId,
      {
        orgId: input.orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId: input.orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  if (replacing !== null) {
    await invitationRepo.revokeInvitation(input.orgId, replacing);
  }

  return invitations;
}

